using System;

using System.Collections.Generic;

using System.ComponentModel;

using System.Globalization;

using System.Resources;

using System.Windows;



namespace VoltrisOptimizer.Services

{

    public enum Language

    {

        Portuguese,

        Spanish,

        English
}


    public struct TranslationStruct
    {
        public string Portuguese;
        public string Spanish;
        public string English;
        public string this[Language lang]
        {
            get => lang == Language.Portuguese ? Portuguese : lang == Language.Spanish ? Spanish : English;
            set { if (lang == Language.Portuguese) Portuguese = value; else if (lang == Language.Spanish) Spanish = value; else English = value; }
        }
    }

    public class LocalizationService : INotifyPropertyChanged

    {

        // =====================================================================
        // ORDEM DE INICIALIZACAO DE CAMPOS ESTATICOS — LER ANTES DE MOVER
        // =====================================================================
        // O C# executa os inicializadores de campo estatico NA ORDEM TEXTUAL e
        // so depois roda o construtor estatico. Como `_instance` instancia a
        // propria classe, TODO campo estatico usado pelo construtor precisa
        // estar declarado ANTES de `_instance` — senao ainda esta null quando o
        // construtor rodar.
        //
        // Foi exatamente o que aconteceu com `_templateRules`: declarado la
        // embaixo, ele era null em InitializeTemplateRules() e derrubava o
        // app com NullReferenceException no type initializer.
        //
        // REGRA: nenhum campo estatico novo pode ser declarado depois de
        // `_instance` se o construtor o utiliza.

        private static readonly List<TemplateRule> _templateRules = new();
        private static bool _templateRulesSorted;
        private static readonly System.TimeSpan _templateMatchTimeout = TimeSpan.FromMilliseconds(120);

        private static readonly LocalizationService _instance = new LocalizationService();

        private Language _currentLanguage;

        private Dictionary<string, TranslationStruct> _strings = null!;



        public static LocalizationService Instance => _instance;



        public event EventHandler? LanguageChanged;

        public event PropertyChangedEventHandler? PropertyChanged;



        protected virtual void OnPropertyChanged(string propertyName)

        {


            PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(propertyName));

        }



        public string this[string key] => GetString(key);



        public Language CurrentLanguage
        {
            get => _currentLanguage;
            set
            {
                if (_currentLanguage != value)
                {
                    var sw = System.Diagnostics.Stopwatch.StartNew();
                    _currentLanguage = value;
                    LoadStrings();
                    sw.Stop();

                    LanguageLogger.Log($"[TRANSLATION_LOAD] Idioma atualizado para: {value}. Tempo de carregamento das traduções: {sw.ElapsedMilliseconds} ms.");

                    // Propagar a cultura para novas threads e para a thread atual
                    var cultureName = value switch
                    {
                        Language.Portuguese => "pt-BR",
                        Language.Spanish => "es-ES",
                        Language.English => "en-US",
                        _ => "pt-BR"
                    };
                    try
                    {
                        var culture = new System.Globalization.CultureInfo(cultureName);
                        System.Globalization.CultureInfo.DefaultThreadCurrentCulture = culture;
                        System.Globalization.CultureInfo.DefaultThreadCurrentUICulture = culture;
                        System.Threading.Thread.CurrentThread.CurrentCulture = culture;
                        System.Threading.Thread.CurrentThread.CurrentUICulture = culture;
                    }
                    catch (Exception exCulture)
                    {
                        LanguageLogger.Log($"[CULTURE_PROPAGATION_ERROR] Falha ao definir cultura '{cultureName}': {exCulture.Message}");
                    }

                    LanguageChanged?.Invoke(this, EventArgs.Empty);
                    OnPropertyChanged(string.Empty);
                    OnPropertyChanged("Item[]");
                }
            }
        }

        private LocalizationService()
        {
            _currentLanguage = Language.Portuguese;

            InitializeStrings();
            InitializeAdditionalStrings();
            InitializeProgressStatusStrings();
            InitializeTemplateRules();
            InitializePageStrings();
            InitializePerformanceProfileStrings();
            LoadStrings();
        }

        private void InitializeAdditionalStrings()
