                // Benchmark - Additional Strings
                ["BenchmarkAfterOptimization"] = new TranslationStruct
                {
                    [Language.Portuguese] = "Após o Benchmark Inicial, aplique as otimizações do Voltris através das páginas de Performance, Modo Gamer ou Benchmark Completo. As otimizações ajustam configurações do Windows como prioridades de CPU, gerenciamento de memória e configurações de energia. O Benchmark Final mede o impacto dessas otimizações com dados concretos.",
                    [Language.Spanish] = "Después del Benchmark Inicial, aplique las optimizaciones de Voltris a través de las páginas de Rendimiento, Modo Gamer o Benchmark Completo. Las optimizaciones ajustan configuraciones de Windows como prioridades de CPU, manejo de memoria y configuraciones de energía. El Benchmark Final mide el impacto de estas optimizaciones con datos concretos.",
                    [Language.English] = "After the Initial Benchmark, apply Voltris optimizations through the Performance, Gamer Mode or Complete Benchmark pages. Optimizations adjust Windows settings such as CPU priorities, memory management and power settings. The Final Benchmark measures the impact of these optimizations with concrete data."
                },
