                // Recovery Info Page
                // Missing Recovery Info Page keys
                ["RecoveryDeleteExplanationPart1"] = new TranslationStruct
                {
                    [Language.Portuguese] = "Quando você exclui um arquivo, o Windows ",
                    [Language.Spanish] = "Cuando elimina un archivo, Windows ",
                    [Language.English] = "When you delete a file, Windows "
                },
                ["RecoveryDeleteExplanationPart2"] = new TranslationStruct
                {
                    [Language.Portuguese] = "não apaga imediatamente os dados",
                    [Language.Spanish] = "no borra inmediatamente los datos",
                    [Language.English] = "does not immediately erase the data"
                },
                ["RecoveryDeleteExplanationPart3"] = new TranslationStruct
                {
                    [Language.Portuguese] = " — ele apenas marca aquele espaço como \"disponível\" na tabela do sistema de arquivos (chamada MFT). Os dados continuam no disco até outro arquivo sobrescrevê-los.",
                    [Language.Spanish] = " — simplemente marca ese espacio como \"disponible\" en la tabla del sistema de archivos (llamada MFT). Los datos permanecen en el disco hasta que otro archivo los sobrescriba.",
                    [Language.English] = " — it simply marks that space as \"available\" in the file system table (called MFT). The data remains on the disk until another file overwrites it."
                },
                ["RecoverySsdTrimExplanationPart1"] = new TranslationStruct
                {
                    [Language.Portuguese] = "SSDs usam um comando chamado ",
                    [Language.Spanish] = "Los SSD utilizan un comando llamado ",
                    [Language.English] = "SSDs use a command called "
                },
                ["RecoverySsdTrimExplanationPart2"] = new TranslationStruct
                {
                    [Language.Portuguese] = "TRIM",
                    [Language.Spanish] = "TRIM",
                    [Language.English] = "TRIM"
                },
                ["RecoverySsdTrimExplanationPart3"] = new TranslationStruct
                {
                    [Language.Portuguese] = " que, quando um arquivo é deletado, informa o controlador do SSD para ",
                    [Language.Spanish] = " que, cuando se elimina un archivo, informa al controlador del SSD para ",
                    [Language.English] = " which, when a file is deleted, informs the SSD controller to "
                },
                ["RecoverySsdTrimExplanationPart4"] = new TranslationStruct
                {
                    [Language.Portuguese] = "zerar fisicamente os setores quase instantaneamente",
                    [Language.Spanish] = "poner a cero físicamente los sectores casi instantáneamente",
                    [Language.English] = "physically zero the sectors almost instantly"
                },
                ["RecoverySsdTrimExplanationPart5"] = new TranslationStruct
                {
                    [Language.Portuguese] = ". Isso protege a saúde do SSD mas torna a recuperação extremamente difícil.",
                    [Language.Spanish] = ". Esto protege la salud del SSD pero hace que la recuperación sea extremadamente difícil.",
                    [Language.English] = ". This protects the health of the SSD but makes recovery extremely difficult."
                },
                ["RecoveryEngineApproachPart1"] = new TranslationStruct
                {
                    [Language.Portuguese] = "O motor de recuperação do Voltris usa ",
                    [Language.Spanish] = "El motor de recuperación de Voltris utiliza ",
                    [Language.English] = "Voltris's recovery engine uses "
                },
                ["RecoveryEngineApproachPart2"] = new TranslationStruct
                {
                    [Language.Portuguese] = "duas abordagens",
                    [Language.Spanish] = "dos enfoques",
                    [Language.English] = "two approaches"
                },
                ["RecoveryEngineApproachPart3"] = new TranslationStruct
                {
                    [Language.Portuguese] = " para encontrar arquivos deletados: leitura da tabela MFT (Scan Rápido) e varredura por assinaturas binárias nos setores do disco (Deep Scan).",
                    [Language.Spanish] = " para encontrar archivos eliminados: lectura de la tabla MFT (Escaneo Rápido) y escaneo por firmas binarias en los sectores del disco (Deep Scan).",
                    [Language.English] = " to find deleted files: reading the MFT table (Quick Scan) and scanning for binary signatures in disk sectors (Deep Scan)."
                },
                ["RecoveryQuickScanMftExplanationPart1"] = new TranslationStruct
                {
                    [Language.Portuguese] = "O Scan Rápido lê a ",
                    [Language.Spanish] = "El Escaneo Rápido lee la ",
                    [Language.English] = "Quick Scan reads the "
                },
                ["RecoveryQuickScanMftExplanationPart2"] = new TranslationStruct
                {
                    [Language.Portuguese] = "MFT (Master File Table)",
                    [Language.Spanish] = "MFT (Master File Table)",
                    [Language.English] = "MFT (Master File Table)"
                },
                ["RecoveryQuickScanMftExplanationPart3"] = new TranslationStruct
                {
                    [Language.Portuguese] = " — a \"tabela de conteúdo\" do disco Windows. Mesmo após a excluso, o registro do arquivo permanece na MFT com o nome, tamanho, extensão e localização no disco preservados.",
                    [Language.Spanish] = " — la \"tabla de contenido\" del disco de Windows. Incluso después de la eliminación, el registro del archivo permanece en la MFT con su nombre, tamaño, extensión y ubicación en el disco preservados.",
                    [Language.English] = " — the \"table of contents\" of the Windows disk. Even after deletion, the file record remains in the MFT with its name, size, extension, and location on the disk preserved."
                },
                ["RecoveryDeepScanExplanationPart1"] = new TranslationStruct
                {
                    [Language.Portuguese] = "O Deep Scan varre ",
                    [Language.Spanish] = "Deep Scan escanea ",
                    [Language.English] = "Deep Scan scans "
                },
                ["RecoveryDeepScanExplanationPart2"] = new TranslationStruct
                {
                    [Language.Portuguese] = "cada byte do disco",
                    [Language.Spanish] = "cada byte del disco",
                    [Language.English] = "every byte of the disk"
                },
                ["RecoveryDeepScanExplanationPart3"] = new TranslationStruct
                {
                    [Language.Portuguese] = " procurando padrões de início de arquivo — chamados de \"assinaturas\" ou \"magic bytes\". Ele não depende da MFT; encontra dados mesmo que o registro do arquivo tenha sido destruído.",
                    [Language.Spanish] = " buscando patrones de inicio de archivo — llamados \"firmas\" o \"magic bytes\". No depende de la MFT; encuentra datos incluso si el registro del archivo ha sido destruido.",
                    [Language.English] = " looking for file header patterns — called \"signatures\" or \"magic bytes\". It does not depend on the MFT; it finds data even if the file record has been destroyed."
                },
                ["RecoveryDeepScanExamplePart1"] = new TranslationStruct
                {
                    [Language.Portuguese] = "Por exemplo: todo arquivo JPG começa com os bytes ",
                    [Language.Spanish] = "Por ejemplo: todo archivo JPG comienza con los bytes ",
                    [Language.English] = "For example: every JPG file starts with the bytes "
                },
                ["RecoveryDeepScanExamplePart2"] = new TranslationStruct
                {
                    [Language.Portuguese] = "FF D8 FF",
                    [Language.Spanish] = "FF D8 FF",
                    [Language.English] = "FF D8 FF"
                },
                ["RecoveryDeepScanExamplePart3"] = new TranslationStruct
                {
                    [Language.Portuguese] = ". O Deep Scan encontra essas sequências em qualquer parte do disco e reconstrói o arquivo a partir dali.",
                    [Language.Spanish] = ". Deep Scan encuentra estas secuencias en cualquier parte del disco y reconstruye el archivo a partir de ahí.",
                    [Language.English] = ". Deep Scan finds these sequences anywhere on the disk and reconstructs the file from there."
                },
                ["RecoveryNameExplanationPart1"] = new TranslationStruct
                {
                    [Language.Portuguese] = "O nome de um arquivo ",
                    [Language.Spanish] = "El nombre de un archivo ",
                    [Language.English] = "The name of a file "
                },
                ["RecoveryNameExplanationPart2"] = new TranslationStruct
                {
                    [Language.Portuguese] = "nunca está dentro dos bytes do arquivo",
                    [Language.Spanish] = "nunca está dentro de los bytes del archivo",
                    [Language.English] = "is never inside the file bytes"
                },
                ["RecoveryNameExplanationPart3"] = new TranslationStruct
                {
