                ["GamerAdaptivePowerTitle"] = new TranslationStruct
                {
                    [Language.Portuguese] = "INTELIGÊNCIA DE ENERGIA ADAPTATIVA",
                    [Language.Spanish] = "INTELIGENCIA DE ENERGÍA ADAPTATIVA",
                    [Language.English] = "ADAPTIVE POWER INTELLIGENCE"
                },
                // New descriptive entries for the Gamer UI
                ["GamerProchotDesc"] = new TranslationStruct
                {
                    [Language.Portuguese] = "BD PROCHOT funciona como uma válvula de segurança que força a CPU a reduzir a frequência quando sensores externos (por exemplo, a GPU) detectam calor excessivo. Desativá‑la remove essa limitação forçada, permitindo que a CPU permaneça em alta velocidade, mas pode elevar a temperatura do sistema. Use com cautela em notebooks ou em máquinas com refrigeração limitada.",
                    [Language.Spanish] = "BD PROCHOT funciona como una válvula de seguridad que obliga a la CPU a reducir su frecuencia cuando sensores externos (por ejemplo, la GPU) detectan calor excesivo. Desactivarla elimina esta limitación forzada, permitiendo que la CPU permanezca a alta velocidad, pero puede elevar la temperatura del sistema. Use con precaución en notebooks o en máquinas con refrigeración limitada.",
                    [Language.English] = "BD PROCHOT acts like a safety valve that forces the CPU to throttle when external sensors (e.g., GPU) signal excessive heat. Disabling it removes this forced slowdown, allowing the CPU to stay at full speed, but may raise system temperatures. Use cautiously on laptops or poorly cooled systems."
                },
                ["GamerSpeedShiftDesc"] = new TranslationStruct
                {
                    [Language.Portuguese] = "SpeedShift funciona como uma caixa de engrenagens inteligente para o processador. Os controles permitem definir a relação mínima e máxima de velocidade (Min/Max) e a preferência de energia‑desempenho (EPP). Aumentar esses limites deixa a CPU rodar mais rápido, porém consome mais energia e gera mais calor – especialmente em notebooks. Ajuste com prudência.",
                    [Language.Spanish] = "SpeedShift funciona como una caja de cambios inteligente para el procesador. Los controles permiten definir la relación mínima y máxima de velocidad (Min/Max) y la preferencia de energía‑rendimiento (EPP). Aumentar estos límites permite que la CPU funcione más rápido, pero consume más energía y genera más calor – especialmente en laptops. Ajuste con prudencia.",
                    [Language.English] = "SpeedShift works like a smart gearbox for the CPU. The sliders let you set the minimum and maximum speed ratios and the Energy‑Performance Preference (EPP). Raising these limits lets the CPU run faster, but consumes more power and generates more heat – especially on laptops. Adjust with care."
                },
                ["GamerAdaptivePowerDesc"] = new TranslationStruct
                {
                    [Language.Portuguese] = "A inteligência adaptativa monitora a temperatura da CPU em tempo real e ajusta dinamicamente os limites de energia para otimizar desempenho sem ultrapassar limites térmicos. Quando a temperatura está baixa, os limites são aumentados; conforme esquenta, eles são reduzidos para evitar throttling.",
                    [Language.Spanish] = "La inteligencia adaptativa monitorea la temperatura de la CPU en tiempo real y ajusta dinámicamente los límites de energía para optimizar el rendimiento sin superar los límites térmicos. Cuando la temperatura es baja, los límites se incrementan; a medida que se calienta, se reducen para evitar throttling.",
                    [Language.English] = "Adaptive intelligence monitors CPU temperature in real time and dynamically adjusts power limits to optimize performance without exceeding thermal thresholds. When temperature is low, limits are raised; as it heats up, they are lowered to prevent throttling."
                },
                ["GamerSpeedShiftEppDesc"] = new TranslationStruct
                {
                    [Language.Portuguese] = "EPP (Energy‑Performance Preference) indica a prioridade entre desempenho e eficiência energética. 0 = foco máximo em desempenho, 15 = foco máximo em economia de energia.",
                    [Language.Spanish] = "EPP (Energy‑Performance Preference) indica la prioridad entre rendimiento y eficiencia energética. 0 = máximo rendimiento, 15 = máxima eficiencia energética.",
                    [Language.English] = "EPP (Energy‑Performance Preference) sets the priority between performance and energy efficiency. 0 = maximum performance, 15 = maximum energy efficiency."
                },
                ["GamerSpeedShiftMaxDesc"] = new TranslationStruct
                {
                    [Language.Portuguese] = "Max Ratio define a frequência máxima que a CPU pode alcançar quando o SpeedShift está habilitado.",
                    [Language.Spanish] = "Max Ratio define la frecuencia máxima que la CPU puede alcanzar cuando SpeedShift está habilitado.",
                    [Language.English] = "Max Ratio sets the maximum frequency the CPU can reach when SpeedShift is enabled."
                },
                ["GamerSpeedShiftMinDesc"] = new TranslationStruct
                {
                    [Language.Portuguese] = "Min Ratio define a frequência mínima que a CPU pode descender antes de subir novamente, evitando quedas bruscas de desempenho.",
                    [Language.Spanish] = "Min Ratio define la frecuencia mínima que la CPU puede descender antes de volver a subir, evitando caídas bruscas de rendimiento.",
                    [Language.English] = "Min Ratio sets the minimum frequency the CPU can drop to before scaling up again, avoiding sudden performance drops."
                },

