                ["Loc_BenchmarkMeasuresYourComputersReal"] = new TranslationStruct
                {
                    [Language.Portuguese] = "O Benchmark mede o desempenho real do seu computador em diversas áreas: processador (CPU), memória RAM, disco (SSD/HDD) e responsividade do sistema. Diferente de benchmarks genéricos, o Voltris mede métricas que impactam diretamente a sua experiência: velocidade de abertura de programas, fluidez da interface e latência do agendador de tarefas do Windows.",
                    [Language.Spanish] = "Benchmark mide el rendimiento real de su computadora en varias áreas: procesador (CPU), memoria RAM, disco (SSD/HDD) y capacidad de respuesta del sistema. A diferencia de los puntos de referencia genéricos, Voltris mide métricas que impactan directamente su experiencia: velocidad de apertura del programa, fluidez de la interfaz y latencia del programador de tareas de Windows.",
                    [Language.English] = "Benchmark measures your computer's real performance in several areas: processor (CPU), RAM memory, disk (SSD/HDD) and system responsiveness. Unlike generic benchmarks, Voltris measures metrics that directly impact your experience: program opening speed, interface fluidity and Windows task scheduler latency."
                },

                ["Loc_RightAfterInstallingVoltrisBefore_2"] = new TranslationStruct
                {
                    [Language.Portuguese] = "• Logo após instalar o Voltris, antes de aplicar otimizações\r\n• Após reinstalar o Windows ou atualizar drivers\r\n• Sempre que quiser ter um ponto de referência atualizado",
                    [Language.Spanish] = "• Inmediatamente después de instalar Voltris, antes de aplicar optimizaciones\r\n• Después de reinstalar Windows o actualizar los controladores\r\n• Siempre que quieras tener un punto de referencia actualizado",
                    [Language.English] = "• Right after installing Voltris, before applying optimizations\r\n• After reinstalling Windows or updating drivers\r\n• Whenever you want to have an updated reference point"
                },

                ["Loc_TheSystemRunsAutomatedTests"] = new TranslationStruct
                {
                    [Language.Portuguese] = "O sistema executa testes automatizados que duram aproximadamente 30 a 60 segundos. O processador, memória e disco são testados com cargas controladas para medir a capacidade real de cada componente.",
                    [Language.Spanish] = "El sistema ejecuta pruebas automatizadas que duran aproximadamente entre 30 y 60 segundos. El procesador, la memoria y el disco se prueban con cargas controladas para medir la capacidad real de cada componente.",
                    [Language.English] = "The system runs automated tests that last approximately 30 to 60 seconds. The processor, memory and disk are tested with controlled loads to measure the actual capacity of each component."
                },

                ["Loc_AfterTheInitialBenchmarkApply"] = new TranslationStruct
                {
                    [Language.Portuguese] = "Após o Benchmark Inicial, aplique as otimizações do Voltris através das páginas de Performance, Modo Gamer ou Benchmark Completo. As otimizações ajustam configurações do Windows como prioridades de CPU, gerenciamento de memória e configurações de energia. O Benchmark Final mede o impacto dessas otimizações com dados concretos.",
                    [Language.Spanish] = "Después de la prueba inicial, aplique las optimizaciones de Voltris a través de las páginas Rendimiento, Modo de jugador o Prueba completa. Las optimizaciones ajustan la configuración de Windows, como las prioridades de la CPU, la administración de la memoria y la configuración de energía. El punto de referencia final mide el impacto de estas optimizaciones con datos concretos.",
                    [Language.English] = "After the Initial Benchmark, apply Voltris optimizations through the Performance, Gamer Mode, or Full Benchmark pages. Optimizations adjust Windows settings like CPU priorities, memory management, and power settings. The Final Benchmark measures the impact of these optimizations with hard data."
                },

                ["Loc_RunsExactlyTheSameTests"] = new TranslationStruct
                {
                    [Language.Portuguese] = "Executa exatamente os mesmos testes do Benchmark Inicial, mas com as otimizações ativas. Execute-o após aplicar otimizações e aguardar pelo menos 15 segundos para o sistema estabilizar. O botão \"Benchmark Completo\" faz tudo isso automaticamente.",
                    [Language.Spanish] = "Ejecuta exactamente las mismas pruebas que el Benchmark inicial, pero con optimizaciones activas. Ejecútelo después de aplicar optimizaciones y esperar al menos 15 segundos para que el sistema se estabilice. El botón \"Completar punto de referencia\" hace todo esto automáticamente.",
                    [Language.English] = "Runs exactly the same tests as the Initial Benchmark, but with optimizations active. Run it after applying optimizations and waiting at least 15 seconds for the system to stabilize. The \"Complete Benchmark\" button does all of this automatically."
                },

                ["Loc_AfterRunningBothBenchmarksClick_2"] = new TranslationStruct
                {
                    [Language.Portuguese] = "Após executar ambos os benchmarks, clique em \"Comparar\" para ver uma tabela detalhada com os valores antes e depois.",
                    [Language.Spanish] = "Después de ejecutar ambos puntos de referencia, haga clic en \"Comparar\" para ver una tabla detallada con los valores antes y después.",
                    [Language.English] = "After running both benchmarks, click \"Compare\" to see a detailed table with before and after values."
                },

                ["Loc_ValuesInGreenPerformanceImprovement"] = new TranslationStruct
                {
                    [Language.Portuguese] = "• Valores em verde = melhoria de desempenho\r\n• Valores em vermelho = redução (raro, variação natural)\r\n• Acima de +5% = ganhos significativos\r\n• Variações de ±2% são normais entre execuções",
                    [Language.Spanish] = "• Valores en verde = mejora del rendimiento\r\n• Valores en rojo = reducción (variación rara y natural)\r\n• Por encima del +5% = ganancias significativas\r\n• Las variaciones de ±2 % son normales entre ejecuciones.",
                    [Language.English] = "• Values in green = performance improvement\r\n• Values in red = reduction (rare, natural variation)\r\n• Above +5% = significant gains\r\n• Variations of ±2% are normal between runs"
                },

                ["Loc_IntensiveMathOperationsFloatingPoint"] = new TranslationStruct
                {
                    [Language.Portuguese] = "Operações matemáticas intensivas (ponto flutuante, inteiros, SHA-256). Testa single-thread e multi-thread.",
                    [Language.Spanish] = "Operaciones matemáticas intensivas (coma flotante, números enteros, SHA-256). Prueba un solo subproceso y varios subprocesos.",
                    [Language.English] = "Intensive math operations (floating point, integers, SHA-256). Tests single-thread and multi-thread."
                },

                ["Loc_RamReadwriteSpeedAccessLatency"] = new TranslationStruct
                {
                    [Language.Portuguese] = "Velocidade de leitura/escrita da RAM, latência de acesso e throughput com padrões sequenciais e aleatórios.",
                    [Language.Spanish] = "Velocidad de lectura/escritura de RAM, latencia de acceso y rendimiento con patrones secuenciales y aleatorios.",
                    [Language.English] = "RAM read/write speed, access latency and throughput with sequential and random patterns."
                },

                ["Loc_ReadingAndWritingTheDisk"] = new TranslationStruct
                {
                    [Language.Portuguese] = "Leitura e escrita do disco com operações sequenciais e aleatórias de 4KB, simulando uso real do sistema.",
                    [Language.Spanish] = "Lectura y escritura del disco con operaciones secuenciales y aleatorias de 4KB, simulando el uso real del sistema.",
                    [Language.English] = "Reading and writing the disk with sequential and random operations of 4KB, simulating real system use."
                },

                ["Loc_WindowsTaskSchedulerLatencyLow"] = new TranslationStruct
                {
                    [Language.Portuguese] = "Latência do agendador de tarefas do Windows. Valores baixos significam maior fluidez.",
                    [Language.Spanish] = "Latencia del programador de tareas de Windows. Los valores bajos significan una mayor fluidez.",
                    [Language.English] = "Windows task scheduler latency. Low values mean greater fluidity."
                },

                ["Loc_GuiResponsivenessWpfDispatcherResponse"] = new TranslationStruct
                {
                    [Language.Portuguese] = "Responsividade da interface gráfica — tempo de resposta do Dispatcher do WPF e fluidez geral.",
                    [Language.Spanish] = "Capacidad de respuesta de la GUI: tiempo de respuesta y fluidez general de WPF Dispatcher.",
                    [Language.English] = "GUI Responsiveness — WPF Dispatcher response time and overall fluidity."
                },

                ["Loc_1RunTheInitialBenchmark"] = new TranslationStruct
                {
                    [Language.Portuguese] = "1. Executa o Benchmark Inicial (linha de base)\r\n2. Aplica as otimizações recomendadas\r\n3. Aguarda 15 segundos para estabilização\r\n4. Executa o Benchmark Final e gera a comparação",
                    [Language.Spanish] = "1. Ejecute el punto de referencia inicial (línea de base)\r\n2. Aplicar las optimizaciones recomendadas.\r\n3. Espere 15 segundos para que se estabilice.\r\n4. Ejecute el Benchmark final y genere la comparación.",
                    [Language.English] = "1. Run the Initial Benchmark (baseline)\r\n2. Apply recommended optimizations\r\n3. Wait 15 seconds for stabilization\r\n4. Run the Final Benchmark and generate the comparison"
                },

                ["Loc_CloseHeavyProgramsBeforeStarting"] = new TranslationStruct
                {
                    [Language.Portuguese] = "• Feche programas pesados antes de iniciar\r\n• Não utilize o computador durante o benchmark\r\n• Mantenha o notebook conectado à tomada\r\n• Execute 2 a 3 vezes e considere a média\r\n• Aguarde pelo menos 2 minutos após ligar o PC\r\n• Se detectar thermal throttling, aguarde o PC esfriar",
                    [Language.Spanish] = "• Cierre los programas pesados antes de comenzar\r\n• No utilice la computadora durante la evaluación comparativa.\r\n• Mantenga el portátil enchufado\r\n• Corre de 2 a 3 veces y considera el promedio.\r\n• Espere al menos 2 minutos después de encender la PC\r\n• Si se detecta estrangulamiento térmico, espere a que la PC se enfríe",
                    [Language.English] = "• Close heavy programs before starting\r\n• Do not use the computer during the benchmark\r\n• Keep the notebook plugged in\r\n• Run 2 to 3 times and consider the average\r\n• Wait at least 2 minutes after turning on the PC\r\n• If thermal throttling is detected, wait for the PC to cool down"
                },

                ["Loc_BenchmarkIsAnAnalysisTool"] = new TranslationStruct
                {
                    [Language.Portuguese] = "O Benchmark é uma ferramenta de análise que mede o desempenho real do seu computador em diversas áreas: processador (CPU), memória RAM, disco (SSD/HDD) e responsividade do sistema operacional.",
                    [Language.Spanish] = "Benchmark es una herramienta de análisis que mide el rendimiento real de tu ordenador en varias áreas: procesador (CPU), memoria RAM, disco (SSD/HDD) y capacidad de respuesta del sistema operativo.",
                    [Language.English] = "Benchmark is an analysis tool that measures your computer's real performance in several areas: processor (CPU), RAM memory, disk (SSD/HDD) and operating system responsiveness."
                },

                ["Loc_UnlikeGenericBenchmarksVoltrisMeasures"] = new TranslationStruct
                {
                    [Language.Portuguese] = "Diferente de benchmarks genéricos, o Voltris mede métricas que impactam diretamente a sua experiência: velocidade de abertura de programas, fluidez da interface e latência do agendador de tarefas do Windows.",
                    [Language.Spanish] = "A diferencia de los puntos de referencia genéricos, Voltris mide métricas que impactan directamente su experiencia: velocidad de apertura del programa, fluidez de la interfaz y latencia del programador de tareas de Windows.",
                    [Language.English] = "Unlike generic benchmarks, Voltris measures metrics that directly impact your experience: program opening speed, interface fluidity and Windows task scheduler latency."
                },

