        private void LoadStrings()
        {
            // Strings já estão carregadas no dicionário
        }

                public string GetString(string key)
        {
            if (string.IsNullOrEmpty(key)) return key;

            if (_strings.TryGetValue(key, out var languageDict)) { var value = languageDict[_currentLanguage]; if (!string.IsNullOrEmpty(value)) return value; }

            if (_currentLanguage != Language.Portuguese)
            {
                // Ordem de resolução (inalterada para tudo que já funciona):
                //   1. dicionário           - acima, sempre tem prioridade
                //   2. LocalizeDynamicString - regras if/StartsWith já existentes
                //   3. motor de templates    - NOVO, só entra se o de cima não resolveu
                // Nenhum passo anterior foi removido ou reordenado.
                string dynamic = LocalizeDynamicString(key, _currentLanguage);
                if (!string.Equals(dynamic, key, StringComparison.Ordinal)) return dynamic;

                string templated = LocalizeByTemplate(key, _currentLanguage);
                if (!string.Equals(templated, key, StringComparison.Ordinal)) return templated;
            }

            return key; // Retorna a chave se não encontrar
        }

        // =====================================================================
        // MOTOR DE TEMPLATES (aditivo - último fallback do GetString)
        // =====================================================================
        // PROBLEMA QUE ELE RESOLVE
        // ------------------------
        // A barra de progresso global, as notificações e vários logs de etapa
        // enviam textos com VARIÁVEIS já interpoladas, por exemplo:
        //     "Limpando cache de navegador: C:\Users\..."  (template: "Limpando cache de navegador: {0}...")
        //     "Executando: DISM /Online /Cleanup-Image"    (template: "Executando: {0}")
        // Nenhuma dessas cadeias sobrevive a uma busca exata no dicionário, porque
        // o dicionário guarda o TEMPLATE, não o texto já preenchido.
        //
        // POR QUE NÃO É MAIS UM IF/STARTSWITH
        // -------------------------------
        // A alternativa seria um bloco condicional novo por mensagem, dentro de
        // LocalizeDynamicString — são ~285 mensagens hoje e o número cresce a
        // cada feature. Um registro declarativo resolve todas de uma vez, e a
        // lista completa fica visível e auditável em um único lugar.
        //
        // GARANTIA DE NÃO REGRESSÃO
        // -------------------------
        // Este motor é o ÚLTIMO recurso. Ele só roda quando o dicionário E o
        // LocalizeDynamicString já falharam. Ou seja: nenhuma tradução que
        // funciona hoje passa por aqui, e nenhuma pode ser alterada por aqui.
        // Se nenhuma regra casar, devolve o texto original — exatamente o
        // comportamento de antes.

        private sealed class TemplateRule
        {
            public string Template = string.Empty;
            public string Spanish = string.Empty;
            public string English = string.Empty;
            public System.Text.RegularExpressions.Regex? Pattern;
            public int LiteralWeight;
        }

        // _templateRules, _templateRulesSorted e _templateMatchTimeout sao
        // declarados no TOPO da classe, antes de `_instance`. Ver o aviso de
        // ordem de inicializacao la em cima.

        private static bool IsAllDigits(string value)
        {
            for (int i = 0; i < value.Length; i++)
            {
                if (value[i] < '0' || value[i] > '9') return false;
            }
            return value.Length > 0;
        }

        /// <summary>
        /// Registra um template com variável. "{0}", "{1}"... viram curingas.
        /// Usado apenas por InitializeTemplateRules().
        /// </summary>
        private static void AddTemplate(string pt, string es, string en)
        {
            if (string.IsNullOrEmpty(pt) || string.IsNullOrEmpty(es) || string.IsNullOrEmpty(en)) return;
            // Template sem variável é caso exato: quem resolve isso é o dicionário.
            if (!System.Text.RegularExpressions.Regex.IsMatch(pt, @"\{\d+\}")) return;

            // Defesa: se algum dia a ordem de inicialização estático mudar, este
            // registro é perdido silenciosamente em vez de derrubar a aplicação.
            if (_templateRules == null) return;

            _templateRules.Add(new TemplateRule { Template = pt, Spanish = es, English = en });
        }

        /// <summary>
        /// Converte o template em Regex ancorada. A parte literal é escapada e o
        /// resto vai como (.*?) preguiçoso. O timeout impede que uma entrada mal
        /// formada trave a UI.
        /// </summary>
        private static void EnsureTemplateRulesCompiled()
        {
            if (_templateRulesSorted) return;

            foreach (var rule in _templateRules)
            {
                var sb = new System.Text.StringBuilder("^");
                int literal = 0;
                int i = 0;
                while (i < rule.Template.Length)
                {
                    if (rule.Template[i] == '{')
                    {
                        int close = rule.Template.IndexOf('}', i);
                        if (close > i)
                        {
                            string token = rule.Template.Substring(i + 1, close - i - 1);
                            if (token.Length > 0 && IsAllDigits(token))
                            {
                                sb.Append("(.*?)");
                                i = close + 1;
                                continue;
                            }
                        }
                    }

                    sb.Append(System.Text.RegularExpressions.Regex.Escape(rule.Template[i].ToString()));
                    if (!char.IsWhiteSpace(rule.Template[i])) literal++;
                    i++;
                }
                sb.Append('$');

                try
                {
                    rule.Pattern = new System.Text.RegularExpressions.Regex(
                        sb.ToString(),
                        System.Text.RegularExpressions.RegexOptions.IgnoreCase |
                        System.Text.RegularExpressions.RegexOptions.Singleline |
                        System.Text.RegularExpressions.RegexOptions.CultureInvariant,
                        _templateMatchTimeout > TimeSpan.Zero ? _templateMatchTimeout : TimeSpan.FromMilliseconds(120));
                    rule.LiteralWeight = literal;
                }
                catch
                {
                    // Template malformado é simplesmente ignorado. Sem exceção,
                    // sem log — é dado de tradução, não caminho de execução.
                }
            }

            // Mais texto literal = mais específico = casa primeiro. Desempate
            // estável pela própria string, para o resultado ser determinístico.
            _templateRules.Sort((a, b) =>
            {
                int byWeight = b.LiteralWeight.CompareTo(a.LiteralWeight);
                if (byWeight != 0) return byWeight;
                return string.CompareOrdinal(a.Template, b.Template);
            });
            _templateRulesSorted = true;
        }

        private string LocalizeByTemplate(string text, Language lang)
        {
            if (string.IsNullOrEmpty(text)) return text;
            if (_templateRules == null || _templateRules.Count == 0) return text;

            EnsureTemplateRulesCompiled();

            foreach (var rule in _templateRules)
            {
                if (rule.Pattern == null) continue;

                System.Text.RegularExpressions.Match match;
                try { match = rule.Pattern.Match(text); }
                catch (System.Text.RegularExpressions.RegexMatchTimeoutException) { continue; }

                if (!match.Success) continue;

                var groups = new List<string>();
                for (int g = 1; g < match.Groups.Count; g++) groups.Add(match.Groups[g].Value);

                string target = lang == Language.English ? rule.English : rule.Spanish;
                if (string.IsNullOrEmpty(target)) continue;

                try { return FormatTemplate(target, groups); }
                catch { continue; }
            }

            return text;
        }

        /// <summary>
        /// Substitui "{0}", "{1}"... pelos valores capturados. Um "{0}" sem
        /// índice é tratado literalmente, como no string.Format.
        /// </summary>
        private static string FormatTemplate(string template, List<string> values)
        {
            if (template.IndexOf('{') < 0) return template;

            var sb = new System.Text.StringBuilder(template.Length + 16);
            int i = 0;
            while (i < template.Length)
            {
                if (template[i] == '{')
                {
                    int close = template.IndexOf('}', i);
                    if (close > i)
                    {
                        string token = template.Substring(i + 1, close - i - 1);
                        int index;
                        if (token.Length > 0 && int.TryParse(token, out index) && index >= 0 && index < values.Count)
                        {
                            sb.Append(values[index]);
                            i = close + 1;
                            continue;
                        }
                    }
                }
                sb.Append(template[i]);
                i++;
            }
            return sb.ToString();
        }

        private string LocalizeDynamicString(string text, Language lang)
        {
            if (string.IsNullOrEmpty(text)) return text;

            // Direct static entries
            if (text.Equals("Cache DNS limpo com sucesso", StringComparison.OrdinalIgnoreCase))
            {
                return lang == Language.English ? "DNS Cache cleared successfully" : "Caché DNS limpiado con éxito";
            }
            if (text.Equals("Catálogo Winsock redefinido", StringComparison.OrdinalIgnoreCase))
            {
                return lang == Language.English ? "Winsock Catalog reset" : "Catálogo Winsock restablecido";
            }
            if (text.Equals("Pilha TCP/IP redefinida", StringComparison.OrdinalIgnoreCase))
            {
                return lang == Language.English ? "TCP/IP Stack reset" : "Pila TCP/IP restablecida";
            }
            if (text.Equals("Concessão DHCP renovada", StringComparison.OrdinalIgnoreCase))
            {
                return lang == Language.English ? "DHCP lease renewed" : "Concesión DHCP renovada";
            }
            if (text.Equals("Parâmetros TCP globais otimizados", StringComparison.OrdinalIgnoreCase))
            {
                return lang == Language.English ? "Global TCP parameters optimized" : "Parámetros TCP globales optimizados";
            }

            // Error messages fallback
            if (text.StartsWith("Erro ao limpar DNS:", StringComparison.OrdinalIgnoreCase))
            {
                return lang == Language.English 
                    ? text.Replace("Erro ao limpar DNS:", "Error clearing DNS Cache:")
                    : text.Replace("Erro ao limpar DNS:", "Error al limpiar DNS:");
            }
            if (text.StartsWith("Erro ao redefinir Winsock:", StringComparison.OrdinalIgnoreCase))
            {
                return lang == Language.English 
                    ? text.Replace("Erro ao redefinir Winsock:", "Error resetting Winsock:")
                    : text.Replace("Erro ao redefinir Winsock:", "Error al restablecer Winsock:");
            }
            if (text.StartsWith("Erro ao redefinir IP:", StringComparison.OrdinalIgnoreCase))
            {
                return lang == Language.English 
                    ? text.Replace("Erro ao redefinir IP:", "Error resetting IP stack:")
                    : text.Replace("Erro ao redefinir IP:", "Error al restablecer IP:");
            }
            if (text.StartsWith("Erro ao renovar DHCP:", StringComparison.OrdinalIgnoreCase))
            {
                return lang == Language.English 
                    ? text.Replace("Erro ao renovar DHCP:", "Error renewing DHCP lease:")
                    : text.Replace("Erro ao renovar DHCP:", "Error al renovar DHCP:");
            }
            if (text.StartsWith("Erro ao otimizar TCP:", StringComparison.OrdinalIgnoreCase))
            {
                return lang == Language.English 
                    ? text.Replace("Erro ao otimizar TCP:", "Error optimizing TCP settings:")
                    : text.Replace("Erro ao otimizar TCP:", "Error al optimizar TCP:");
            }

            // DNS settings
            if (text.StartsWith("DNS customizado aplicado em ", StringComparison.OrdinalIgnoreCase))
            {
                return lang == Language.English
                    ? text.Replace("DNS customizado aplicado em ", "Custom DNS applied on ")
                    : text.Replace("DNS customizado aplicado em ", "DNS personalizado aplicado en ");
            }
            if (text.StartsWith("Erro ao aplicar DNS em ", StringComparison.OrdinalIgnoreCase))
            {
                return lang == Language.English
                    ? text.Replace("Erro ao aplicar DNS em ", "Error applying DNS on ")
                    : text.Replace("Erro ao aplicar DNS em ", "Error al aplicar DNS en ");
            }
            if (text.StartsWith("DNS de ", StringComparison.OrdinalIgnoreCase) && text.EndsWith(" restaurado para DHCP", StringComparison.OrdinalIgnoreCase))
            {
                return lang == Language.English
                    ? text.Replace("DNS de ", "DNS of ").Replace(" restaurado para DHCP", " restored to DHCP")
                    : text.Replace("DNS de ", "DNS de ").Replace(" restaurado para DHCP", " restablecido a DHCP");
            }
            if (text.StartsWith("Erro ao restaurar DNS para DHCP em ", StringComparison.OrdinalIgnoreCase))
            {
                return lang == Language.English
                    ? text.Replace("Erro ao restaurar DNS para DHCP em ", "Error restoring DNS to DHCP on ")
                    : text.Replace("Erro ao restaurar DNS para DHCP em ", "Error al restaurar DNS a DHCP en ");
            }

            // Gamer/Optimization history dynamic strings
            if (text.StartsWith("Perfil de otimização aplicado para o jogo: ", StringComparison.OrdinalIgnoreCase))
            {
                return lang == Language.English
                    ? text.Replace("Perfil de otimização aplicado para o jogo: ", "Optimization profile applied for game: ")
                    : text.Replace("Perfil de otimização aplicado para o jogo: ", "Perfil de optimización aplicado para el juego: ");
            }
            if (text.StartsWith("Novo perfil de otimização personalizado criado para: ", StringComparison.OrdinalIgnoreCase))
            {
                return lang == Language.English
                    ? text.Replace("Novo perfil de otimização personalizado criado para: ", "New custom optimization profile created for: ")
                    : text.Replace("Novo perfil de otimização personalizado criado para: ", "Nuevo perfil de optimización personalizado creado para: ");
            }
            if (text.StartsWith("Jogo removido da biblioteca: ", StringComparison.OrdinalIgnoreCase))
            {
                return lang == Language.English
                    ? text.Replace("Jogo removido da biblioteca: ", "Game removed from library: ")
                    : text.Replace("Jogo removido da biblioteca: ", "Juego eliminado de la biblioteca: ");
            }
            if (text.StartsWith("Limpeza de cache (Shaders): ", StringComparison.OrdinalIgnoreCase) && text.EndsWith(" liberados.", StringComparison.OrdinalIgnoreCase))
            {
                return lang == Language.English
                    ? text.Replace("Limpeza de cache (Shaders): ", "Cache cleanup (Shaders): ").Replace(" liberados.", " freed.")
                    : text.Replace("Limpeza de cache (Shaders): ", "Limpieza de caché (Shaders): ").Replace(" liberados.", " liberados.");
            }
            if (text.StartsWith("DNS alterado para ", StringComparison.OrdinalIgnoreCase) && text.EndsWith(".", StringComparison.OrdinalIgnoreCase))
            {
                return lang == Language.English
                    ? text.Replace("DNS alterado para ", "DNS changed to ")
                    : text.Replace("DNS alterado para ", "DNS cambiado a ");
            }
            if (text.StartsWith("Modo Gamer ativado para ", StringComparison.OrdinalIgnoreCase))
            {
                return lang == Language.English
                    ? text.Replace("Modo Gamer ativado para ", "Gamer Mode activated for ")
                    : text.Replace("Modo Gamer ativado para ", "Modo Gamer activado para ");
            }
            if (text.Contains(" otimizações de '", StringComparison.OrdinalIgnoreCase) && text.EndsWith("' aplicadas.", StringComparison.OrdinalIgnoreCase))
            {
                return lang == Language.English
                    ? text.Replace(" otimizações de '", " optimizations of '").Replace("' aplicadas.", "' applied.")
                    : text.Replace(" otimizações de '", " optimizaciones de '").Replace("' aplicadas.", "' aplicadas.");
            }
            if (text.StartsWith("Otimização completa: ", StringComparison.OrdinalIgnoreCase) && text.EndsWith(" melhorias aplicadas.", StringComparison.OrdinalIgnoreCase))
            {
                return lang == Language.English
                    ? text.Replace("Otimização completa: ", "Complete optimization: ").Replace(" melhorias aplicadas.", " improvements applied.")
                    : text.Replace("Otimização completa: ", "Optimización completa: ").Replace(" melhorias aplicadas.", " mejoras aplicadas.");
            }
            if (text.EndsWith(" otimizações do sistema foram restauradas.", StringComparison.OrdinalIgnoreCase))
            {
                return lang == Language.English
                    ? text.Replace(" otimizações do sistema foram restauradas.", " system optimizations were restored.")
                    : text.Replace(" otimizações do sistema foram restauradas.", " optimizaciones del sistema foram restauradas.");
            }

            // Cleaner / Scheduler history dynamic strings
            if (text.StartsWith("Limpeza Rápida: ", StringComparison.OrdinalIgnoreCase) || text.StartsWith("Limpeza Rápida: ", StringComparison.OrdinalIgnoreCase))
            {
                return lang == Language.English
                    ? text.Replace("Limpeza Rápida: ", "Quick Cleanup: ").Replace("Limpeza Rápiva: ", "Quick Cleanup: ").Replace(" liberados", " freed")
                    : text.Replace("Limpeza Rápida: ", "Limpieza Rápida: ").Replace("Limpeza Rápiva: ", "Limpieza Rápida: ").Replace(" liberados", " liberados");
            }
            if (text.StartsWith("Limpeza realizada com sucesso: ", StringComparison.OrdinalIgnoreCase))
            {
                return lang == Language.English
                    ? text.Replace("Limpeza realizada com sucesso: ", "Cleanup performed successfully: ").Replace(" liberados de ", " freed from ").Replace(" módulos.", " modules.")
                    : text.Replace("Limpeza realizada com sucesso: ", "Limpieza realizada con éxito: ").Replace(" liberados de ", " liberados de ").Replace(" módulos.", " módulos.");
            }
            if (text.StartsWith("Limpeza profunda: ", StringComparison.OrdinalIgnoreCase))
            {
                return lang == Language.English
                    ? text.Replace("Limpeza profunda: ", "Deep cleanup: ").Replace(" liberados", " freed")
                    : text.Replace("Limpeza profunda: ", "Limpieza profunda: ").Replace(" liberados", " liberados");
            }
            if (text.StartsWith("Tarefa '", StringComparison.OrdinalIgnoreCase) && text.EndsWith("' executada automaticamente.", StringComparison.OrdinalIgnoreCase))
            {
                return lang == Language.English
                    ? text.Replace("Tarefa '", "Task '").Replace("' executada automaticamente.", "' executed automatically.")
                    : text.Replace("Tarefa '", "Tarea '").Replace("' executada automaticamente.", "' ejecutada automáticamente.");
            }
            if (text.StartsWith("Modo Gamer ativado: ", StringComparison.OrdinalIgnoreCase))
            {
                var replaced = text;
                if (lang == Language.English)
                {
                    replaced = replaced.Replace("Modo Gamer ativado: ", "Gamer Mode activated: ").Replace("Otimização Global", "Global Optimization");
                }
                else if (lang == Language.Spanish)
                {
                    replaced = replaced.Replace("Modo Gamer ativado: ", "Modo Gamer activado: ").Replace("Otimização Global", "Optimización Global");
                }
                return replaced;
            }

            return text;
        }

        public void SetLanguage(Language language)
        {
            CurrentLanguage = language;
        }

        public string GetLanguageName(Language language)
        {
            return language switch
            {
                Language.Portuguese => GetString("Portuguese"),
                Language.Spanish => GetString("Spanish"),
                Language.English => GetString("English"),
                _ => "Unknown"
            };
}
        }
}





